style.css:
@-moz-document domain("roblox.com") {
/* CLOUDY BLUE THEME */

:root {
    --color-common-black: #d8f0ff;
    --color-neutral-background: #eaf7ff;
    --color-primary: #83c9ed;
}

/* FONDO */
body {
    background-color: #dff3ff !important;
}

/* BARRA SUPERIOR */
#navbar,
.navbar {
    background-color: #a9dcf5 !important;
}

/* PANELES */
.content,
.container-main,
.main-content {
    background-color: #eaf7ff !important;
}

/* TARJETAS */
.game-card,
.card {
    background-color: #d1edfc !important;
    border-radius: 14px !important;
}

/* BOTONES */
button,
.btn-primary {
    background-color: #91d1f0 !important;
    border-radius: 10px !important;
}

/* ENLACES */
a:hover {
    color: #438db9 !important;
}

/* BORDES */
input,
textarea {
    border-color: #a9dcf5 !important;
    border-radius: 10px !important;
}
}
